CREATE TABLE IF NOT EXISTS project_milestones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, code text NOT NULL, title text NOT NULL, description text, status text NOT NULL DEFAULT 'pending', target_date date, completed_at timestamptz, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id, code));